    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount, bool nonOwner) public payable {
        require(address(this).balance >= amount);
        payable(address(c)).transfer(amount);
        address caller = nonOwner ? address(0xBEEF) : address(this);
        uint cBalanceBefore = address(c).balance;
        bool reverted;
        if (caller == address(this)) {
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        } else {
            try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        }
        assert(!reverted == (caller == c.owner()) && reverted == (caller != c.owner()));
