contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint v) public payable {
        require(address(this).balance >= 0);

        // The test contract is the owner because it deployed C.
        // Fund c so that withdraw has Ether to send.
        uint fundAmount = 1;
        require(address(this).balance >= fundAmount);
        (bool sent, ) = address(c).call{value: fundAmount}("");
        require(sent);

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount();

        bool reverted;
        try c.withdraw(v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount();

        assert(beforeDeposits == afterDeposits);
        assert((reverted == (v > beforeBalance)));
        if (!reverted) {
            assert(afterBalance == beforeBalance - v);
        } else {
            assert(afterBalance == beforeBalance);
        }
    }

    receive() external payable {}
}

